const os = require('os');

console.log("--- System Diagnostics ---");

// OS Information
console.log(`OS Platform: ${os.platform()}`);
console.log(`OS Architecture: ${os.arch()}`);
console.log(`System Uptime: ${Math.round(os.uptime() / 3600)} hours`);

// CPU Information
const cores = os.cpus();
console.log(`CPU Cores: ${cores.length}`);
console.log(`CPU Model: ${cores[0].model}`);

// Memory Information (Returned in Bytes, converting to Gigabytes)
const totalMemGB = (os.totalmem() / 1024 / 1024 / 1024).toFixed(2);
const freeMemGB = (os.freemem() / 1024 / 1024 / 1024).toFixed(2);

console.log(`Total RAM: ${totalMemGB} GB`);
console.log(`Free RAM: ${freeMemGB} GB`);
